style.css:
@-moz-document domain("roblox.com") {
/* Global dark background */
  body, html, .container, .content, .section, .game-page {
    background-color: #000 !important;
    color: #ccc !important;
  }

  /* Remove white/gray backgrounds */
  .header, .footer, .navbar, .game-card, .game-tile, .profile-about, .section-content,
  .modal-content, .tab-content, .card-container, .card {
    background-color: #111 !important;
    border-color: #222 !important;
  }

  /* Text color */
  h1, h2, h3, h4, h5, h6, p, span, a, label, .text {
    color: #ccc !important;
  }

  /* Make buttons dark */
  .btn, button, .btn-primary, .btn-secondary, .btn-default {
    background-color: #222 !important;
    color: #fff !important;
    border: 1px solid #444 !important;
  }

  .btn:hover, button:hover {
    background-color: #333 !important;
  }

  /* Darken input fields */
  input, textarea, select {
    background-color: #111 !important;
    color: #fff !important;
    border: 1px solid #444 !important;
  }

  /* Scrollbar (optional, aesthetic) */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #111;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #666;
  }

  /* Hide promotional ads or unwanted sections (optional) */
  .advertisement, .sponsored-games, .sponsored-section {
    display: none !important;
  }

  /* Make profile avatars dark-filtered (optional) */
  img {
    filter: brightness(0.8) contrast(1.2);
  }
}
